public sealed class Editor {
    private sealed class Memento { internal string Text = ""; internal int Caret; }
    private readonly Stack<Memento> _history = new();
    private string _text = ""; private int _caret;
    public object Save() {
        var m = new Memento { Text = _text, Caret = _caret };
        _history.Push(m); return m;      // caller sees only an opaque handle
    }
    public void Undo() {
        if (_history.Count == 0) return;
        var m = _history.Pop(); (_text, _caret) = (m.Text, m.Caret);
    }
}
